// Business Rule: ASYNC | Update | Table: sysapproval_approver
// Filter Condition: State changes to Approved OR State changes to Rejected

(function executeRule(current, previous) {

    if (current.source_table != 'x_birl3_clm_clm_new_credit_request') return;

    var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
    if (!gr.get(current.document_id + '')) return;

    var needsUpdate = false;
    var currentState = (current.state + '').toLowerCase();

    // Save approved_limit if approved and not already set
    if (currentState == 'approved') {
        if (!gr.approved_limit || parseFloat(gr.approved_limit) == 0) {
            gr.setValue('approved_limit', parseFloat(gr.requested_limit) || 0);
            needsUpdate = true;
        }
    }

    // Read comment from sys_journal_field for both approve and reject
    var jGr = new GlideRecord('sys_journal_field');
    jGr.addQuery('element_id', current.sys_id + '');
    jGr.addQuery('name', 'sysapproval_approver');
    jGr.addQuery('element', 'comments');
    jGr.orderByDesc('sys_created_on');
    jGr.setLimit(1);
    jGr.query();

    if (jGr.next()) {
        var commentValue = (jGr.value + '').trim();
        if (commentValue != '' && commentValue != 'null') {
            gr.comments = commentValue;
            needsUpdate = true;
        }
    }

   if (needsUpdate) {

    var originalInitiator = gr.initiator + '';

    gr.initiator = originalInitiator;

    gr.setWorkflow(false);
    gr.autoSysFields(false);

    gr.update();
}

})(current, previous);
